    def pushDominoes(self, dominoes):
        N = len(dominoes)
        force = [0] * N

        # Populate forces going from left to right
        f = 0
        for i in xrange(N):
            if dominoes[i] == 'R': f = N
            elif dominoes[i] == 'L': f = 0
            else: f = max(f-1, 0)
            force[i] += f

        # Populate forces going from right to left
        f = 0
        for i in xrange(N-1, -1, -1):
            if dominoes[i] == 'L': f = N
            elif dominoes[i] == 'R': f = 0
            else: f = max(f-1, 0)
            force[i] -= f

        return "".join('.' if f==0 else 'R' if f > 0 else 'L'
                       for f in force)

class Solution(object):
    def pushDominoes(self, dominoes):
        """
        :type dominoes: str
        :rtype: str
        """
        s = list(dominoes)
        n = len(s)
        p1 = 0
        left = 'L'
        while p1 < n:
            p2 = p1
            while p2 < n and s[p2] == '.':
                p2 += 1
            if p2 < n:
                right = s[p2]
            else:
                right = "R"
            if left == right:
                cur_left = p1
                cur_right = p2 - 1
                while cur_left <= cur_right:
                    s[cur_left] = left
                    cur_left += 1
            elif left == "R" and right == "L":
                cur_left = p1
                cur_right = p2 - 1
                while cur_left < cur_right:
                    s[cur_left] = "R"
                    s[cur_right] = "L"
                    cur_left += 1
                    cur_right -= 1
            left = right
            p1 = p2 + 1
        return "".join(s)
